mapper.select:
SELECT LOGIN_ID
FROM `users`
WHERE NAME = #{name}
  AND EMAIL = #{email}
    LIMIT 1

mapper.update:
UPDATE `users`
SET PASSWORD = #{password},
    UPDATED_AT = NOW()
WHERE LOGIN_ID = #{loginId}
  AND EMAIL = #{email}

UPDATE `users`
BIRTH_DATE = #{birthDate}, NICKNAME = #{nickname}, EMAIL = #{email}, PROFILE_IMAGE_URL = #{profileImageUrl}, UPDATED_AT = NOW()
WHERE LOGIN_ID = #{loginId}

UPDATE `users`
SET LAST_LOGIN_AT = NOW()
WHERE LOGIN_ID = #{loginId}

UPDATE `users`
SET USER_STATUS = 'DORMANT'
WHERE LOGIN_ID IN (
    SELECT temp.LOGIN_ID FROM (
       SELECT LOGIN_ID
       FROM `users`
       WHERE USER_STATUS = 'ACTIVE'
         AND (
           LAST_LOGIN_AT < #{cutoffDate}
               OR (LAST_LOGIN_AT IS NULL AND CREATED_AT < #{cutoffDate})
           )
   ) AS temp
)

UPDATE `users`
SET USER_STATUS = 'ACTIVE',
    LAST_LOGIN_AT = NOW()
WHERE LOGIN_ID = #{loginId}
  AND EMAIL = #{email}
  AND USER_STATUS = 'DORMANT'
